const body = $input.first().json.body ?? $input.first().json;
const trace_id = body.trace_id ?? 'no-trace-id';
const payload = body.event?.payload ?? {};
const WEAVIATE_URL = 'http://weaviate:8080';
const OLLAMA_URL = 'http://host.docker.internal:11434';

try {
  const content = payload.content || '';
  const filename = payload.filename || ('ingested-' + Date.now() + '.txt');
  const labels = payload.labels || [];

  if (!content) {
    return [{ json: { ok: false, trace_id, error: { message: 'No content provided', node: 'kb.ingest' } } }];
  }

  // Ensure collections exist
  const ensureCollection = async function(name) {
    try {
      await helpers.httpRequest({ url: WEAVIATE_URL + '/v1/schema/' + name, method: 'GET', json: true });
    } catch (e) {
      await helpers.httpRequest({
        url: WEAVIATE_URL + '/v1/schema',
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: { class: name },
        json: true
      });
    }
  };
  await ensureCollection('VERBA_DOCUMENTS');
  await ensureCollection('VERBA_Embedding_nomic_embed_text');

  // Chunk content (~250 words per chunk, 50 word overlap)
  const words = content.split(/\s+/);
  const CHUNK_SIZE = 250;
  const OVERLAP = 50;
  const chunks = [];

  if (words.length <= CHUNK_SIZE) {
    chunks.push({ content: content, content_without_overlap: content, start_i: 0, end_i: words.length });
  } else {
    for (let i = 0; i < words.length; i += (CHUNK_SIZE - OVERLAP)) {
      const end = Math.min(i + CHUNK_SIZE, words.length);
      const overlapStart = (i === 0) ? 0 : i + OVERLAP;
      chunks.push({
        content: words.slice(i, end).join(' '),
        content_without_overlap: words.slice(Math.min(overlapStart, end), end).join(' '),
        start_i: i,
        end_i: end
      });
      if (end >= words.length) break;
    }
  }

  // Get embeddings from Ollama
  const embeddings = [];
  for (const chunk of chunks) {
    const embedRes = await helpers.httpRequest({
      url: OLLAMA_URL + '/api/embed',
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: { model: 'nomic-embed-text', input: chunk.content },
      json: true
    });
    embeddings.push(embedRes.embeddings[0]);
  }

  // Create document in VERBA_DOCUMENTS
  const docMeta = JSON.stringify({ Embedder: 'Ollama', Model: 'nomic-embed-text', Chunker: 'Token', ingested_via: 'kb.ingest' });
  const docRes = await helpers.httpRequest({
    url: WEAVIATE_URL + '/v1/objects',
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: {
      class: 'VERBA_DOCUMENTS',
      properties: { title: filename, content: content, extension: filename.split('.').pop() || 'txt', fileSize: content.length, labels: labels, source: '', meta: docMeta, metadata: '' }
    },
    json: true
  });
  const docUuid = docRes.id;

  // Create chunks in VERBA_Embedding_nomic_embed_text
  const chunkIds = [];
  for (let i = 0; i < chunks.length; i++) {
    const chunkRes = await helpers.httpRequest({
      url: WEAVIATE_URL + '/v1/objects',
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: {
        class: 'VERBA_Embedding_nomic_embed_text',
        properties: { content: chunks[i].content, chunk_id: i, doc_uuid: docUuid, title: filename, pca: [0, 0, 0], start_i: chunks[i].start_i, end_i: chunks[i].end_i, content_without_overlap: chunks[i].content_without_overlap, labels: labels },
        vector: embeddings[i]
      },
      json: true
    });
    chunkIds.push(chunkRes.id);
  }

  return [{ json: { ok: true, trace_id, result: { doc_uuid: docUuid, filename: filename, chunks_created: chunkIds.length, chunk_ids: chunkIds } } }];
} catch (err) {
  return [{ json: { ok: false, trace_id, error: { message: err.message, node: 'kb.ingest', details: String(err) } } }];
}

