            'Limit Mode': cs('dropdown','Autocut','',['Autocut','Fixed']),
            'Limit/Sensitivity': cs('number',1,''),
            'Chunk Window': cs('number',1,''),
            'Threshold': cs('number',80,'')
          }
        }
      }
    }
  };

  const ragConfig = payload.rag_config || defaultRAG;

  const res = await helpers.httpRequest({
    url: VERBA_URL + '/api/query',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Origin':       'http://verba:8000'
